const webhook =
  $('Webhook').first().json;

const sisId =
  webhook.query?.sis_id;

return [
  {
    json: {
      receivedSisId: sisId ?? null,
      query: webhook.query
    }
  }
];

const pages = $input.all();

const targetSisId =
  $('Code in JavaScript').first().json.receivedSisId;

if (!targetSisId) {
  throw new Error('Student SIS ID was not received from the webhook');
}

let student = null;

for (const page of pages) {
  const users = page.json.results ?? [];

  student = users.find(
    user => String(user.sis_id) === String(targetSisId)
  );

  if (student) {
    break;
  }
}

if (!student) {
  return [
    {
      json: {
        found: false,
        sisId: targetSisId,
        pagesSearched: pages.length
      }
    }
  ];
}

return [
  {
    json: {
      found: true,
      student: {
        qwicklyId: student.id,
        firstName: student.first_name,
        lastName: student.last_name,
        email: student.email,
        sisId: student.sis_id,
        lmsId: student.lms_id
      },
      pagesSearched: pages.length
    }
  }
];

