const sisId = $json.query?.sis_id;

if (!sisId) {
  throw new Error('Missing sis_id');
}

// Temporary FYP data.
// Student Profile API is emulated.
// Attendance data will later come from Qwickly.

const students = {
  '104404156': {
    sisId: '104404156',
    name: 'Fredly Benny Anak Vilen',
    programme: 'Bachelor of Computer Science',

    attendance: [
      {
        intake: 'Semester 2, 2026',
        percentage: 87
      }
    ]
  }
};

const student = students[String(sisId)];

if (!student) {
  throw new Error('Student not found');
}

function attendanceStatus(percentage) {
  if (percentage >= 80) return 'Good';
  if (percentage >= 40) return 'Fair';
  if (percentage >= 1) return 'Poor';

  return 'Nil';
}

const attendance = student.attendance.map(item => ({
  ...item,
  status: attendanceStatus(item.percentage)
}));

const now = new Date();

const formattedDate = new Intl.DateTimeFormat('en-GB', {
  day: 'numeric',
  month: 'long',
  year: 'numeric'
}).format(now);

return [
  {
    json: {
      success: true,

      student: {
        sisId: student.sisId,
        name: student.name,
        programme: student.programme
      },

      report: {
        reference: `ATT/${student.sisId}/${now.getFullYear()}`,
        date: formattedDate,
        period: 'Semester 2, 2026'
      },

      attendance
    }
  }
];

