const sessions = $json.results ?? [];

return sessions.map(session => ({
  json: {
    sessionId: session.id,
    title: session.title,
    startTime: session.start_time,
    method: session.method,
    groupId: session.group_id,
    sectionId: session.section_id
  }
}));

// Student found earlier from SIS ID
const studentResult =
  $('Find ID').first().json;

if (!studentResult?.found) {
  throw new Error(
    'Qwickly student could not be found'
  );
}

const qwicklyUserId =
  Number(studentResult.student.qwicklyId);


// All session-record API responses
const sessionResponses =
  $('Get Session Records').all();


// Qwickly attendance statuses
const statusItems =
  $('Get Attendance Statuses').all();


// Depending on how the HTTP node returns the array,
// flatten the status data.
let statuses = [];

for (const item of statusItems) {

  if (Array.isArray(item.json)) {
    statuses.push(...item.json);
  } else {
    statuses.push(item.json);
  }

}


function getStatus(statusId) {

  return statuses.find(
    status =>
      Number(status.id) ===
      Number(statusId)
  );

}


const records = [];

let present = 0;
let absent = 0;
let excused = 0;


// Process every Qwickly session
for (const sessionResponse of sessionResponses) {

  const sessionRecords =
    sessionResponse.json.results ?? [];


  // Find this student's record
  const studentRecord =
    sessionRecords.find(
      record =>
        Number(record.user_id) ===
        qwicklyUserId
    );


  // Student has no record for this session
  if (!studentRecord) {

    records.push({
      sessionId:
        sessionRecords[0]?.parent_session
        ?? null,

      status: 'No Record'
    });

    continue;
  }


  const status =
    getStatus(studentRecord.status_id);


  const statusName =
    status?.name ?? 'Unknown';


  if (statusName === 'Present') {
    present++;
  }

  else if (statusName === 'Absent') {
    absent++;
  }

  else if (statusName === 'Excused') {
    excused++;
  }


  records.push({

    sessionId:
      studentRecord.parent_session,

    recordId:
      studentRecord.id,

    statusId:
      studentRecord.status_id,

    status:
      statusName,

    points:
      status?.points ?? null,

    absence:
      status?.absence ?? null,

    timeCreated:
      studentRecord.time_created,

    method:
      studentRecord.mobile_data?.method
      ?? null

  });

}


// Excused is currently excluded because
// Qwickly returned null points/absence for it.
const countedSessions =
  present + absent;


const percentage =
  countedSessions > 0
    ? Math.round(
        (present / countedSessions) * 100
      )
    : null;


return [
  {
    json: {

      student: {
        qwicklyId:
          qwicklyUserId,

        sisId:
          studentResult.student.sisId,

        name:
          `${studentResult.student.firstName} ${studentResult.student.lastName}`
      },

      attendance: {

        totalSessions:
          sessionResponses.length,

        countedSessions,

        present,

        absent,

        excused,

        percentage

      },

      records

    }
  }
];
